	if err != nil {
		t.Fatal(err)
	}
	s := Wrap(srv)
	if s.Underlying() != srv {
		t.Error("the typed server does not hold its server")
	}
	if err := s.Set(Patch{}); err != nil {
		t.Error(err)
	}
	_ = s.Get()
	full := Patch{
		SupportedFormats:   new([]SupportedFormatStruct),
		CurrentConnections: new([]TransportConfigurationStruct),
	}
	values := full.AttributeValues()
	// The stored values read back into a State, field by field.
	var back State
	back.FromAttributeValues(func(id uint32) (any, bool) { v, ok := values[id]; return v, ok })
